import { get } from './store.js';
import { selectDegeneretteDefaultSymbol, DEGENERETTE_FALLBACK_SYMBOL } from './degenerette-default.js';
import { CHAIN, CONTRACTS, ETH_DIVISOR } from './chain-config.js';
import { degeneretteLimits, degeneretteStakeUnit, DEGENERETTE_HERO_COUNT } from './degenerette.js';

export const DEGENERETTE_QUICKPLAY_CHANGED = 'degenerette:quickplay-changed';
const DEFAULT_BET = Object.freeze({
  currency: 1, amountPerTicketWei: String(1_000n * 10n ** 18n),
  ticketCount: 1, symbol: DEGENERETTE_FALLBACK_SYMBOL, preferClaimable: false,
});

function key(owner) {
  if (!/^0x[0-9a-f]{40}$/i.test(String(owner || ''))) return null;
  return `degenerus:degenerette-last-manual:v1:${CHAIN.id}:${CONTRACTS.GAME.toLowerCase()}:${owner.toLowerCase()}`;
}

function symbolKey(owner) {
  return `${key(owner) || `degenerus:degenerette-last-manual:v1:${CHAIN.id}:${CONTRACTS.GAME.toLowerCase()}:guest`}:symbol`;
}

function validSymbol(symbol) {
  return Number.isInteger(symbol) && symbol >= 0 && symbol < DEGENERETTE_HERO_COUNT;
}

function normalize(bet) {
  try {
    const { currency, ticketCount, symbol } = bet;
    const limits = degeneretteLimits(currency);
    if (![0, 1].includes(currency) || !limits
      || !Number.isInteger(ticketCount) || ticketCount < 1 || ticketCount > limits.maxSpins
      || !Number.isInteger(symbol) || symbol < 0 || symbol >= DEGENERETTE_HERO_COUNT) return null;
    const amount = BigInt(bet.amountPerTicketWei);
    if (amount <= 0n || amount % degeneretteStakeUnit(currency) !== 0n
      || amount * (currency === 0 ? BigInt(ETH_DIVISOR) : 1n) < limits.minBetFullScale) return null;
    return { currency, amountPerTicketWei: String(amount), ticketCount, symbol,
      preferClaimable: currency === 0 && bet.preferClaimable === true };
  } catch { return null; }
}

export function readDegeneretteQuickPlay(owner) {
  const storageKey = key(owner);
  const automatic = defaultSymbols.get(String(owner || '').toLowerCase());
  const symbol = automatic?.level === defaultLevel() ? automatic.symbol : DEGENERETTE_FALLBACK_SYMBOL;
  let result = { ...DEFAULT_BET, symbol, saved: false };
  try {
    const bet = storageKey && normalize(JSON.parse(localStorage.getItem(storageKey)));
    if (bet) result = { ...bet, saved: true };
  } catch { /* unavailable or invalid local storage uses the advertised default */ }
  try {
    const symbol = JSON.parse(localStorage.getItem(symbolKey(owner)));
    if (validSymbol(symbol)) result.symbol = symbol;
  } catch { /* retain the saved/default symbol */ }
  return result;
}

// The cabinet picker changes only the symbol; it never changes the wager or
// turns the default into a manual purchase. A new manual purchase resets it.
export function writeDegeneretteQuickPlaySymbol(owner, symbol) {
  if (!validSymbol(symbol)) return false;
  try {
    localStorage.setItem(symbolKey(owner), JSON.stringify(symbol));
    globalThis.document?.dispatchEvent(new CustomEvent(DEGENERETTE_QUICKPLAY_CHANGED));
    return true;
  } catch { return false; }
}

// Only call after a manual placement confirms. Drafts, quests and quick plays
// must not replace the last manual purchase, nor store a boon-inflated stake.
export function rememberDegeneretteManualBet(owner, bet) {
  const storageKey = key(owner);
  const normalized = normalize(bet);
  if (!storageKey || !normalized) return false;
  try {
    localStorage.setItem(storageKey, JSON.stringify(normalized));
    localStorage.removeItem(symbolKey(owner));
    globalThis.document?.dispatchEvent(new CustomEvent(DEGENERETTE_QUICKPLAY_CHANGED));
    return true;
  } catch { return false; }
}


const defaultSymbols = new Map();
const defaultRequests = new Map();
const defaultLevel = () => Number(get('app.lastDay')?.roll1?.purchaseLevel) || 0;

export async function refreshDegeneretteQuickPlayDefault(owner, { fresh = false } = {}) {
  if (!key(owner)) return;
  owner = owner.toLowerCase();
  const level = defaultLevel();
  const cached = defaultSymbols.get(owner);
  if (!fresh && cached?.level === level && Date.now() - cached.at < 30_000) return;
  const requestKey = `${owner}:${level}`;
  if (defaultRequests.has(requestKey)) return defaultRequests.get(requestKey);
  const request = (async () => {
    const [{ fetchJSON }, { readDeityPassCatalog }] = await Promise.all([import('./api.js'), import('./passes.js')]);
    const [tickets, deityCatalog] = await Promise.all([
      level > 0 ? fetchJSON(`/player/${owner}/tickets/by-trait?level=${level}`, { priority: 'background' }).catch(() => null) : null,
      readDeityPassCatalog().catch(() => null),
    ]);
    if (defaultLevel() !== level) return;
    const symbol = selectDegeneretteDefaultSymbol({ tickets, deityCatalog, owner });
    defaultSymbols.set(owner, { level, symbol, at: Date.now() });
    globalThis.document?.dispatchEvent(new CustomEvent(DEGENERETTE_QUICKPLAY_CHANGED));
  })().catch(() => {}).finally(() => defaultRequests.delete(requestKey));
  defaultRequests.set(requestKey, request);
  return request;
}
